for line in lines:
    line = line.rstrip()
    if not line or line.startswith('#'):
        continue

    # Check if it's a top-level category (no leading whitespace, ends with colon)
    if not line.startswith(' ') and not line.startswith('\t') and line.endswith(':'):
        current_category = line.rstrip(':').strip()
        if current_category not in data:
            data[current_category] = {}
        current_subcategory = None  # Reset subcategory when entering new top-level category
    elif line.startswith(' ') or line.startswith('\t'):
        stripped = line.strip()
        # Check if it's a subcategory header (ends with colon)
        if stripped.endswith(':'):
            current_subcategory = stripped.rstrip(':').strip()
            if current_category:
                if current_subcategory not in data[current_category]:
                    data[current_category][current_subcategory] = []
        else:
            # It's a choice line - belongs to current_subcategory under current_category
            if current_category and current_subcategory:
                choice_text = stripped.split()[0] if stripped.split() else stripped
                # Extract the annotation part at the end
                # Format: "        local file                           [property LocalSource]"
                # The choice name is everything before the last [...], but there might be spaces
                # Let's split and find the last part that looks like [annotation]
                parts = stripped.split()
                # Find the annotation tag
                annotation_match = re.search(r'\[.*?\]$', stripped)
                if annotation_match:
                    annotation_str = annotation_match.group()
                    choice_name = ' '.join(parts[:-1])  # Everything before the annotation
                    # But this might include extra spaces - let's clean it
                    choice_name = choice_name.strip()
                    # Actually looking at file: "        local file                           [property LocalSource]"
                    # The choice name is "local file" not "local file                           "
                    # Let me parse smarter
                    choice_name = stripped.split()[0]  # "local"
                    # Actually "local file" is the name, not just "local"
                    # Let me just split by whitespace and join everything except the annotation
                    text_before_annotation = stripped.split(annotation_match.group()[1:-1])[0].split()
                    choice_name = ' '.join(text_before_annotation).strip()
                    # This is getting messy. Let me just use regex to extract properly
                # Better approach: split the line, find where [ starts
                idx = stripped.rfind('[')
                if idx != -1:
                    annotation = stripped[idx:]  # includes the bracket
                    choice_part = stripped[:idx].strip()  # everything before [
                    choice_name = choice_part.split()[-1] if choice_part.split() else choice_part.split()[0]
                    # Actually choice is "local file" which is two words
                    choice_name = choice_part.strip()
                    data[current_category][current_subcategory].append({
                        'name': choice_name,
                        'annotation': annotation.strip('[]')  # remove []
                    })
                else:
                    # No annotation - shouldn't happen but handle gracefully
                    data[current_category][current_subcategory].append({
                        'name': stripped.strip(),
                        'annotation': ''
                    })
    elif line.startswith('\t'):
        # Tab-indented might also be choices - handle similarly
        stripped = line.strip()
        if stripped.endswith(':'):
            current_subcategory = stripped.rstrip(':').strip()
            if current_category:
                if current_subcategory not in data[current_category]:
                    data[current_category][current_subcategory] = []
        else:
            if current_category and current_subcategory:
                idx = stripped.rfind('[')
                if idx != -1:
                    annotation = stripped[idx:]
                    choice_part = stripped[:idx].strip()
                    choice_name = choice_part
                    data[current_category][current_subcategory].append({
                        'name': choice_name,
                        'annotation': annotation.strip('[]')
                    })

# Print parsed data for debugging
print(json.dumps(data, indent=2))
